interface EventListener<T> { void onEvent(T event); }

class InMemoryEventBus {
    private final Map<Class<?>, List<EventListener<Object>>> listeners = new HashMap<>();

    <T> void subscribe(Class<T> eventType, EventListener<Object> listener) {
        listeners.computeIfAbsent(eventType, k -> new ArrayList<>()).add(listener);
    }

    void publish(Object event) {
        listeners.getOrDefault(event.getClass(), List.of()).forEach(l -> l.onEvent(event));
    }
}

