class OrdersModuleCorrect {
    private final InventoryModuleApi inventory; // bezposrednie wywolanie - Lesson17
    private final InMemoryEventBus eventBus;

    OrdersModuleCorrect(InventoryModuleApi inventory, InMemoryEventBus eventBus) {
        this.inventory = inventory;
        this.eventBus = eventBus;
    }

    boolean placeOrder(String orderId, String sku, String email) {
        if (!inventory.isAvailable(sku)) return false; // ODPOWIEDZ potrzebna PRZED kontynuacja
        inventory.reserve(sku);
        eventBus.publish(new OrderPlaced(orderId, email)); // FAKT, ktory juz sie wydarzyl
        return true;
    }
}
